export const schoolProgressScale=[{code:'B',label:'Beginning'},{code:'B+',label:'Beginning +'},{code:'D',label:'Developing'},{code:'D+',label:'Developing +'},{code:'M',label:'Mastering'},{code:'M+',label:'Mastering +'}];
export const packById=id=>standardsPacks.find(pack=>pack.id===id);
export function validateStandardsSelection(value){
 if(value===undefined)return undefined;
 if(!value || value.version!==1 || typeof value.deferred!=='boolean' || !Array.isArray(value.frameworks) || value.frameworks.length>4 || typeof value.notes!=='string' || value.notes.length>4000 || !['framework','b-m-plus'].includes(value.judgmentScale || 'framework'))throw Error('Choose valid assessment standards.');
 if(value.deferred&&value.frameworks.length || !value.deferred&&!value.frameworks.length)throw Error('Choose standards or explicitly choose to decide later.');
 const seen=new Set();const frameworks=value.frameworks.map(row=>{const pack=packById(row?.id);if(!pack || seen.has(row.id) || !pack.scopes.some(scope=>scope.id===row.scope))throw Error('Choose a valid framework and year, stage or qualification.');seen.add(row.id);return {id:row.id,scope:row.scope,edition:pack.edition};});
 const allowedDimensions=['knowledge','skills','understanding'];
 const dimensions=value.dimensions ?? (frameworks.some(row=>['ib-pyp','ipc'].includes(row.id))?['knowledge','skills']:[]);
 if(!Array.isArray(dimensions)||dimensions.length>3||new Set(dimensions).size!==dimensions.length||dimensions.some(id=>!allowedDimensions.includes(id)))throw Error('Check the assessment dimensions.');
 return {version:1,deferred:value.deferred,frameworks,judgmentScale:value.judgmentScale || 'framework',dimensions:[...dimensions],understandingMode:'evidence-profile',notes:value.notes.trim()};
}
